// TRANSIT IQ — Dashboard Application Logic
// All transit/speed/route data is fetched from static JSON generated by
// backend/scripts/build_dashboard_data.py (see data/ for the raw sources).

const PNAMES = ['בוקר מוקדם', 'שעות הבוקר', 'לפני הצהריים', 'צהריים', 'אחר הצהריים', 'שעת שיא ערב', 'ערב / לילה'];
const PTIMES = ['≈05–07', '≈07–09', '≈09–12', '≈12–15', '≈15–17', '≈17–19', '≈19–24'];
const DAYNAMES = ['ראשון', 'שני', 'שלישי', 'רביעי', 'חמישי'];
const DAYAB = ['א׳', 'ב׳', 'ג׳', 'ד׳', 'ה׳'];

// ---- State ----
let state = {
  day: 'avg',
  period: 'all',
  layers: { speed: true, cong: false },
  areaFilter: null // { bbox, boundary } of the selected neighbourhood, or null for city-wide
};

let D = {
  center: [32.08, 34.78],
  bbox: { minlat: 32.02, maxlat: 32.14, minlon: 34.74, maxlon: 34.82 },
  segments: [],
  speedProfile: null // filled from data/kpis.json — average speed per period, P1..P7
};

// ---- Dynamic Color Scales (Theme Aware) ----
const themeColors = {
  dark: {
    s1: '#7a0c2e', s2: '#c0142d', s3: '#e8472b', s4: '#f59e0b', s5: '#facc15', s6: '#4ade80', s7: '#22d3ee', line: '#2b3346'
  },
  light: {
    s1: '#991b1b', s2: '#dc2626', s3: '#ef4444', s4: '#f97316', s5: '#d97706', s6: '#16a34a', s7: '#2563eb', line: '#cbd5e1'
  }
};

function col(v) {
  const isLight = document.body.classList.contains('light-theme');
  const colors = isLight ? themeColors.light : themeColors.dark;
  if (v == null || v <= 0) return colors.line;
  if (v < 8) return colors.s1;
  if (v < 12) return colors.s2;
  if (v < 16) return colors.s3;
  if (v < 22) return colors.s4;
  if (v < 30) return colors.s5;
  if (v < 45) return colors.s6;
  return colors.s7;
}

// Each segment carries a flat 35-value array: 5 days (d_1..d_5) x 7 periods (h_1..h_7).
// Average across whichever day(s)/period(s) are currently selected.
function segSpeed(speedsArray) {
  const days = state.day === 'avg' ? [0, 1, 2, 3, 4] : [state.day];
  const periods = state.period === 'all' ? [0, 1, 2, 3, 4, 5, 6] : [state.period];
  let sum = 0, n = 0;
  for (const d of days) {
    for (const h of periods) {
      const v = speedsArray[d * 7 + h];
      if (v && v > 0) { sum += v; n++; }
    }
  }
  return n ? sum / n : null;
}

// ---- Neighbourhood area filter ----
// Standard ray-casting point-in-ring test. `ring` is a GeoJSON-style array
// of [lon, lat] pairs.
function rayCastInRing(lat, lon, ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const xi = ring[i][0], yi = ring[i][1];
    const xj = ring[j][0], yj = ring[j][1];
    const intersect = ((yi > lat) !== (yj > lat)) &&
      (lon < (xj - xi) * (lat - yi) / (yj - yi) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function pointInPolygonRings(lat, lon, rings) {
  if (!rayCastInRing(lat, lon, rings[0])) return false; // outside exterior ring
  for (let i = 1; i < rings.length; i++) {
    if (rayCastInRing(lat, lon, rings[i])) return false; // inside a hole
  }
  return true;
}

function geometryContains(lat, lon, geometry) {
  if (!geometry) return false;
  if (geometry.type === 'Polygon') return pointInPolygonRings(lat, lon, geometry.coordinates);
  if (geometry.type === 'MultiPolygon') return geometry.coordinates.some(poly => pointInPolygonRings(lat, lon, poly));
  return false;
}

// area = { bbox: {min_lat,max_lat,min_lon,max_lon}, boundary: GeoJSON|null }
// bbox is always checked first (cheap pre-filter); when a real boundary
// polygon exists it's the precise test, otherwise the bbox itself is the area.
function pointInArea(lat, lon, area) {
  const b = area.bbox;
  if (lat < b.min_lat || lat > b.max_lat || lon < b.min_lon || lon > b.max_lon) return false;
  return area.boundary ? geometryContains(lat, lon, area.boundary) : true;
}

function segmentInArea(pl, area) {
  const latlngs = pl.getLatLngs();
  for (const ll of latlngs) {
    if (pointInArea(ll.lat, ll.lng, area)) return true;
  }
  return false;
}

// Recomputed once per neighbourhood switch (not per recolor() call) since
// it's the relatively expensive part — recolor() just does a Set lookup.
let areaMembership = null;
function computeAreaMembership() {
  areaMembership = state.areaFilter ? new Set(polys.filter(pl => segmentInArea(pl, state.areaFilter))) : null;
}

// Called by neighbourhood.js when the selected neighbourhood changes.
// label is the Hebrew name shown in the KPI caption, or null for city-wide.
function applyNeighbourhoodFilter(area, label) {
  state.areaFilter = area;
  computeAreaMembership();
  const kSegD = document.getElementById('kSegD');
  if (kSegD) kSegD.textContent = label ? `בגבולות ${label}` : 'ברחבי העיר';
  recolor();
}

// ---- Map Setup ----
const tiles = {
  dark: {
    base: 'https://{s}.basemaps.cartocdn.com/dark_nolabels/{z}/{x}/{y}{r}.png',
    labels: 'https://{s}.basemaps.cartocdn.com/dark_only_labels/{z}/{x}/{y}{r}.png'
  },
  light: {
    base: 'https://{s}.basemaps.cartocdn.com/light_nolabels/{z}/{x}/{y}{r}.png',
    labels: 'https://{s}.basemaps.cartocdn.com/light_only_labels/{z}/{x}/{y}{r}.png'
  }
};

// Check local storage for saved theme
const initialTheme = localStorage.getItem('theme') || 'dark';
if (initialTheme === 'light') {
  document.body.classList.add('light-theme');
}

const map = L.map('map', { zoomControl: false, attributionControl: false, preferCanvas: true })
  .setView(D.center, 15);
L.control.zoom({ position: 'topleft' }).addTo(map);

const activeMapTheme = initialTheme === 'light' ? 'light' : 'dark';
let baseTileLayer = L.tileLayer(tiles[activeMapTheme].base, { maxZoom: 19, subdomains: 'abcd' }).addTo(map);
let labelTileLayer = L.tileLayer(tiles[activeMapTheme].labels, { maxZoom: 19, subdomains: 'abcd', opacity: initialTheme === 'light' ? 0.8 : 0.7 }).addTo(map);

const speedLayer = L.layerGroup().addTo(map);
const congLayer = L.layerGroup();
const borderLayer = L.layerGroup().addTo(map); // Layer group for drawing the city border

// Drawing/selecting individual bus routes is handled by neighbourhood.js
// (the "קווי אוטובוס בשכונה" list), which owns its own route layer.

function drawNeighborhoodBorder(geoJson) {
  borderLayer.clearLayers();
  if (geoJson) {
    L.geoJSON(geoJson, {
      style: {
        color: '#ff8a3d',
        weight: 3,
        opacity: 0.8,
        fillOpacity: 0.02,
        dashArray: '6 4'
      }
    }).addTo(borderLayer);
  }
}

// ---- Build Polylines Once, Recolor on Update ----
const polys = [];
function buildSpeed() {
  speedLayer.clearLayers();
  polys.length = 0;
  const isLight = document.body.classList.contains('light-theme');
  const colors = isLight ? themeColors.light : themeColors.dark;

  D.segments.forEach(s => {
    const latlngs = s.coordinates;
    const pl = L.polyline(latlngs, { color: colors.line, weight: 3, opacity: .9 });
    pl._speeds = s.speeds; // 35 metrics array

    pl.on('mouseover', function () { this.setStyle({ weight: 6 }) });
    pl.on('mouseout', function () { this.setStyle({ weight: this._w || 3 }) });
    pl.on('click', function () {
      const v = segSpeed(this._speeds);

      L.popup().setLatLng(this.getLatLngs()[Math.floor(this.getLatLngs().length / 2)])
        .setContent('<div class="pp">מהירות אוטובוס במקטע<br><b>' + (v ? v.toFixed(1) : '—') + ' קמ״ש</b></div>').openOn(map);
    });
    polys.push(pl);
    speedLayer.addLayer(pl);
  });

  // polys was just rebuilt from scratch — recompute which of them fall
  // inside the currently-selected neighbourhood (if any). Doing this here,
  // rather than only in applyNeighbourhoodFilter, keeps membership correct
  // even if a neighbourhood was selected before segments finished loading,
  // and after buildSpeed() re-runs on theme toggle.
  computeAreaMembership();
}

function recolor() {
  let sum = 0, n = 0, below = 0, tot = 0;
  congLayer.clearLayers();

  const isLight = document.body.classList.contains('light-theme');
  const emptyColor = isLight ? '#cbd5e1' : '#222a3a';

  polys.forEach(pl => {
    const v = segSpeed(pl._speeds);
    const inArea = !areaMembership || areaMembership.has(pl);

    const c = v == null ? emptyColor : col(v);
    let w = v == null ? 3 : v < 16 ? 4 : 3;
    pl._w = w;

    // Segments are always drawn for full-city context — only the KPI totals
    // below are scoped to the selected neighbourhood.
    pl.setStyle({ color: c, opacity: 0.9, weight: w });

    if (v != null && inArea) {
      sum += v;
      n++;
      tot++;
      if (v < 15) {
        below++;
        const cl = L.polyline(pl.getLatLngs(), { color: '#ff2d55', weight: 6, opacity: .85 });
        congLayer.addLayer(cl);
      }
    }
  });
  document.getElementById('kAvg').textContent = n ? (sum / n).toFixed(1) : '—';
  document.getElementById('kCong').textContent = tot ? Math.round(below / tot * 100) : '—';
  const segCount = areaMembership ? areaMembership.size : D.segments.length;
  if (D.segments && D.segments.length > 0) {
    document.getElementById('kSeg').textContent = segCount.toLocaleString('he-IL');
  }

  // Labels
  const dl = state.day === 'avg' ? 'ממוצע ימי חול (א׳–ה׳)' : 'יום ' + DAYNAMES[state.day];
  const pl = state.period === 'all' ? 'כל שעות היום' : PNAMES[state.period] + ' ' + PTIMES[state.period];
  document.getElementById('nowLbl').textContent = (state.day === 'avg' ? 'ממוצע' : DAYAB[state.day]) + ' · ' + (state.period === 'all' ? 'כל היום' : PNAMES[state.period]);
  document.getElementById('nowSub').textContent = dl + ' · ' + pl;
  document.getElementById('kAvgD').textContent = pl;
}

// ---- UI Bindings ----
const daysEl = document.getElementById('days');
DAYAB.forEach((d, i) => {
  const b = document.createElement('div');
  b.className = 'day';
  b.textContent = d;
  b.onclick = () => { state.day = i; syncDays(); recolor(); };
  daysEl.appendChild(b);
});
const avgBtn = document.createElement('div');
avgBtn.className = 'day avg on';
avgBtn.textContent = 'ממוצע';
avgBtn.onclick = () => { state.day = 'avg'; syncDays(); recolor(); };
daysEl.appendChild(avgBtn);

function syncDays() {
  [...daysEl.children].forEach((c, i) => {
    c.classList.toggle('on', (i < 5 && state.day === i) || (i === 5 && state.day === 'avg'));
  });
}

const perEl = document.getElementById('periods');
PNAMES.forEach((nm, i) => {
  const r = document.createElement('div');
  r.className = 'prow';
  r.innerHTML = '<span class="pn">P' + (i + 1) + '</span><span class="pl">' + nm + '</span><span class="pt">' + PTIMES[i] + '</span>';
  r.onclick = () => { state.period = i; syncPer(); recolor(); };
  perEl.appendChild(r);
});
const allp = document.getElementById('allp');
allp.onclick = () => { state.period = 'all'; syncPer(); recolor(); };

function syncPer() {
  [...perEl.children].forEach((c, i) => c.classList.toggle('on', state.period === i));
  allp.classList.toggle('on', state.period === 'all');
}

// Layer Toggles
document.querySelectorAll('.toggle').forEach(t => {
  t.onclick = () => {
    const k = t.dataset.layer;
    state.layers[k] = !state.layers[k];
    t.classList.toggle('on', state.layers[k]);
    applyLayers();
  };
});

function applyLayers() {
  toggleL(speedLayer, state.layers.speed);
  toggleL(congLayer, state.layers.cong);
}

function toggleL(layer, on) {
  if (on) {
    if (!map.hasLayer(layer)) map.addLayer(layer);
  } else {
    if (map.hasLayer(layer)) map.removeLayer(layer);
  }
}

// Profile Sparkline — average bus speed per time-of-day period (P1..P7),
// computed by the backend pipeline from the real BUS_SPEED data.
const sparkEl = document.getElementById('spark');
function buildSpark() {
  sparkEl.innerHTML = '';
  if (!D.speedProfile) return;
  const known = D.speedProfile.filter(v => v != null);
  const max = known.length ? Math.max(...known) : 1;
  D.speedProfile.forEach((v, i) => {
    const s = document.createElement('div');
    s.className = 'spk';
    const h = v == null ? 0 : (v / max * 100);
    s.innerHTML = '<span class="val">' + (v == null ? '—' : v.toFixed(0)) + '</span><div class="bar" style="height:' + h + '%;background:' + col(v) + '"></div><span class="lab">P' + (i + 1) + '</span>';
    s.onclick = () => {
      state.period = i;
      syncPer();
      recolor();
      updateSpark();
    };
    sparkEl.appendChild(s);
  });
}

function updateSpark() {
  [...sparkEl.children].forEach((c, i) => c.classList.toggle('on', state.period === i));
}

// Play Animation
let playing = null;
document.getElementById('play').onclick = function () {
  if (playing) {
    clearInterval(playing);
    playing = null;
    this.textContent = '▶ הרצת יום';
    return;
  }
  this.textContent = '⏸ עצור';
  let p = 0;
  state.period = 0;
  syncPer();
  recolor();
  updateSpark();
  playing = setInterval(() => {
    p = (p + 1) % 7;
    state.period = p;
    syncPer();
    recolor();
    updateSpark();
  }, 1100);
};

document.getElementById('reset').onclick = () => {
  if (playing) {
    clearInterval(playing);
    playing = null;
    document.getElementById('play').textContent = '▶ הרצת יום';
  }
  state.day = 'avg';
  state.period = 'all';
  // clearAllRoutes/renderRouteList live in neighbourhood.js, loaded after
  // this script, but resolved lazily here since reset only ever runs from
  // a user click (well after both scripts have executed).
  if (typeof clearAllRoutes === 'function') {
    clearAllRoutes();
    renderRouteList();
  }
  syncDays();
  syncPer();
  recolor();
  updateSpark();
  map.setView(D.center, 15);
};

// ---- Theme Toggle Logic ----
const themeToggleBtn = document.getElementById('themeToggle');
function updateMapTheme() {
  const isLight = document.body.classList.contains('light-theme');
  const currentTheme = isLight ? 'light' : 'dark';

  // Set leafet base tile layer url
  baseTileLayer.setUrl(tiles[currentTheme].base);
  labelTileLayer.setUrl(tiles[currentTheme].labels);
  labelTileLayer.setOpacity(isLight ? 0.8 : 0.7);

  // Rebuild/recolor features with theme-aware colors
  buildSpeed();
  recolor();
  buildSpark();
  drawNeighborhoodBorder(D.borderGeoJson); // Redraw border to update outline contrast
  recolorImportedLayers();
}

themeToggleBtn.onclick = () => {
  document.body.classList.toggle('light-theme');
  const isLight = document.body.classList.contains('light-theme');
  localStorage.setItem('theme', isLight ? 'light' : 'dark');
  updateMapTheme();
};

async function initAll() {
  try {
    document.getElementById('kSeg').textContent = 'טוען…';
    document.getElementById('kAvg').textContent = 'טוען…';

    const [borderRes, speedsRes, kpisRes] = await Promise.all([
      fetch('./data/border.json'),
      fetch('./data/speeds.json'),
      fetch('./data/kpis.json'),
    ]);

    if (borderRes.ok) {
      const geoJson = await borderRes.json();
      D.borderGeoJson = geoJson;
      drawNeighborhoodBorder(geoJson);

      if (geoJson.geometry.coordinates[0].length > 0) {
        const coords = geoJson.geometry.coordinates[0];
        const lats = coords.map(c => c[1]);
        const lons = coords.map(c => c[0]);
        D.bbox.minlat = Math.min(...lats);
        D.bbox.maxlat = Math.max(...lats);
        D.bbox.minlon = Math.min(...lons);
        D.bbox.maxlon = Math.max(...lons);
        D.center = [(D.bbox.minlat + D.bbox.maxlat) / 2, (D.bbox.minlon + D.bbox.maxlon) / 2];
        map.setView(D.center, 13);
      }
    }

    if (speedsRes.ok) {
      D.segments = await speedsRes.json();
      document.getElementById('kSeg').textContent = D.segments.length.toLocaleString('he-IL');
    } else {
      document.getElementById('kSeg').textContent = 'שגיאת נתונים';
    }

    if (kpisRes.ok) {
      const kpis = await kpisRes.json();
      D.speedProfile = kpis.speed_profile || null;
    }

    buildSpeed();
    buildSpark();
    recolor();
    updateSpark();
    applyLayers();

  } catch (e) {
    console.error('Dashboard data load failed', e);
    document.getElementById('kSeg').textContent = 'שגיאת רשת';
  }
}

initAll();

// ---- Import Layer ----
const importedLayers = [];

const IMPORT_EXT_RE = /\.(geojson|json|kml|zip)$/i;

function escHtml(v) {
  return String(v).replace(/[&<>"']/g, c => (
    { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
  ));
}

function importedColor() {
  return document.body.classList.contains('light-theme') ? '#0891b2' : '#22d3ee';
}

document.getElementById('importFile').addEventListener('change', function (e) {
  Array.from(e.target.files).forEach(importFile);
  this.value = '';
});

// Drag-and-drop onto the map. dragenter/dragleave bubble from child elements
// (map tiles, controls), so track depth instead of toggling on every event.
const mapWrap = document.getElementById('mapwrap');
let dragDepth = 0;

mapWrap.addEventListener('dragenter', e => {
  e.preventDefault();
  if (++dragDepth === 1) mapWrap.classList.add('drop-active');
});
mapWrap.addEventListener('dragover', e => e.preventDefault());
mapWrap.addEventListener('dragleave', () => {
  if (--dragDepth <= 0) {
    dragDepth = 0;
    mapWrap.classList.remove('drop-active');
  }
});
mapWrap.addEventListener('drop', e => {
  e.preventDefault();
  dragDepth = 0;
  mapWrap.classList.remove('drop-active');
  Array.from(e.dataTransfer.files).forEach(file => {
    if (IMPORT_EXT_RE.test(file.name)) importFile(file);
  });
});

function importFile(file) {
  const name = file.name.replace(/\.[^.]+$/, '');
  const ext = file.name.split('.').pop().toLowerCase();

  if (ext === 'kml') {
    const reader = new FileReader();
    reader.onload = ev => {
      try {
        const doc = new DOMParser().parseFromString(ev.target.result, 'text/xml');
        addImportedLayer(toGeoJSON.kml(doc), name);
      } catch {
        alert('קובץ KML לא תקין');
      }
    };
    reader.readAsText(file);

  } else if (ext === 'zip') {
    const reader = new FileReader();
    reader.onload = async ev => {
      try {
        const zip = await JSZip.loadAsync(ev.target.result);
        const entries = Object.values(zip.files).filter(f => !f.dir);

        const shpEntry = entries.find(f => /\.shp$/i.test(f.name));
        const dbfEntry = entries.find(f => /\.dbf$/i.test(f.name));
        const prjEntry = entries.find(f => /\.prj$/i.test(f.name));

        if (!shpEntry || !dbfEntry) {
          alert('קובץ ZIP לא מכיל קבצי Shapefile (.shp + .dbf)');
          return;
        }

        const [shpBuf, dbfBuf, prjText] = await Promise.all([
          shpEntry.async('arraybuffer'),
          dbfEntry.async('arraybuffer'),
          prjEntry ? prjEntry.async('string') : Promise.resolve(null)
        ]);

        const geojson = shp.combine([shp.parseShp(shpBuf, prjText), shp.parseDbf(dbfBuf)]);
        addImportedLayer(geojson, name);
      } catch (err) {
        console.error('Shapefile import error:', err);
        alert('שגיאה בייבוא Shapefile: ' + err.message);
      }
    };
    reader.readAsArrayBuffer(file);

  } else if (ext === 'geojson' || ext === 'json') {
    const reader = new FileReader();
    reader.onload = ev => {
      try {
        addImportedLayer(JSON.parse(ev.target.result), name);
      } catch {
        alert('קובץ GeoJSON לא תקין');
      }
    };
    reader.readAsText(file);

  } else {
    alert('סוג קובץ לא נתמך: .' + ext + '\nניתן לייבא GeoJSON, KML או Shapefile בקובץ ZIP.');
  }
}

function addImportedLayer(geojson, name) {
  const color = importedColor();

  const layer = L.geoJSON(geojson, {
    style: { color, weight: 2, opacity: 0.9, fillOpacity: 0.15 },
    pointToLayer: (f, latlng) => L.circleMarker(latlng, {
      radius: 6, color, weight: 2, fillColor: color, fillOpacity: 0.8
    }),
    onEachFeature: (f, l) => {
      if (!f.properties) return;
      const rows = Object.entries(f.properties)
        .filter(([, v]) => v != null)
        .map(([k, v]) => '<tr><td style="color:var(--ink3);padding-left:8px">' + escHtml(k) + '</td><td>' + escHtml(v) + '</td></tr>')
        .join('');
      if (rows) l.bindPopup('<table style="font-size:12px;direction:ltr;border-collapse:collapse">' + rows + '</table>');
    }
  }).addTo(map);

  try { map.fitBounds(layer.getBounds(), { padding: [30, 30] }); } catch {}

  importedLayers.push({ layer, name, visible: true });
  renderImportedList();
}

// Imported layers are styled at import time, so they need re-styling when the
// theme flips alongside the rest of the map features.
function recolorImportedLayers() {
  const color = importedColor();
  importedLayers.forEach(({ layer }) => {
    layer.setStyle(l => l instanceof L.CircleMarker
      ? { color, weight: 2, fillColor: color, fillOpacity: 0.8 }
      : { color, weight: 2, opacity: 0.9, fillOpacity: 0.15 });
  });
}

function renderImportedList() {
  const el = document.getElementById('importedList');
  el.innerHTML = importedLayers.map((item, i) =>
    '<li class="imported-item' + (item.visible ? ' on' : '') + '">' +
    '<div class="sw" onclick="toggleImportedLayer(' + i + ')"></div>' +
    '<span class="imported-name" title="' + escHtml(item.name) + '">' + escHtml(item.name) + '</span>' +
    '<button class="imported-remove" onclick="removeImportedLayer(' + i + ')" title="הסר שכבה">✕</button>' +
    '</li>'
  ).join('');
}

function toggleImportedLayer(idx) {
  const item = importedLayers[idx];
  item.visible = !item.visible;
  if (item.visible) map.addLayer(item.layer);
  else map.removeLayer(item.layer);
  renderImportedList();
}

function removeImportedLayer(idx) {
  map.removeLayer(importedLayers[idx].layer);
  importedLayers.splice(idx, 1);
  renderImportedList();
}

// Expose necessary functions globally for onclick attributes in dynamically rendered elements
window.toggleImportedLayer = toggleImportedLayer;
window.removeImportedLayer = removeImportedLayer;
